// js
const terms = get(ctx.subject.employment, 'terms', {});
const rate = get(terms, 'rate', {});
const hours = get(
	terms,
	'normal_hours_per_day',
	get(terms, 'statutory_work_category', null) === 'HAZARDOUS'
		? ctx.lookup.hazardous_normal_hours_per_day
		: ctx.lookup.normal_hours_per_day
);
// s.64 pays at the s.62 rate: a monthly wage already pays the holiday (s.56(1)), so 1×; a day or hour
// rate has no weekly-holiday pay, so 2× (s.62(2)). An entry does not say which holiday, so a daily
// worker's traditional or annual holiday (s.62(1), 1×) is paid above the minimum.
const multiple = rate.unit === 'MONTHLY' ? ctx.lookup.paid_multiple : ctx.lookup.unpaid_multiple;
return (ctx.day_rate / hours) * multiple * ctx.entry.quantity;

